{
  "didatica": [
    {
      "campo": "resolucao.antes.texto",
      "depois": "Sem forças dissipativas (como o atrito e a resistência do ar), a energia mecânica se conserva. No ponto mais alto, a pessoa está parada e só tem energia potencial gravitacional. No ponto mais baixo, ela para por um instante e toda essa energia virou energia elástica. 'Mínimo valor de k' quer dizer que, no limite, ela chega ao chão com velocidade zero, 30 m abaixo do ponto de partida.",
      "motivo": "Explica 'dissipativas' e deixa o texto mais curto, com frases mais diretas."
    },
    {
      "campo": "resolucao.passos[4].tipo",
      "depois": "calcular",
      "motivo": "O passo isola k e é uma conta. O passo de concluir deve ligar o resultado à letra."
    },
    {
      "campo": "resolucao.passos[4].conta",
      "depois": "k = 2 × 36 000 ÷ 400 = 180",
      "motivo": "Conta mais curta, para caber na tela do celular."
    },
    {
      "campo": "resolucao.passos",
      "depois": [
        {
          "faz": "Ache a queda total no caso-limite",
          "conta": "h = 30 m",
          "porque": "No limite de segurança, a pessoa para exatamente ao chegar ao chão. As dimensões dela são desprezadas, então ela desce os 30 m do viaduto.",
          "tipo": "localizar"
        },
        {
          "faz": "Calcule quanto o elástico estica",
          "conta": "x = 30 − 10 = 20 m",
          "porque": "Os primeiros 10 m são queda livre, com o elástico solto. Só o que passa do comprimento relaxado conta como deformação.",
          "tipo": "calcular"
        },
        {
          "faz": "Iguale as energias nos dois extremos",
          "conta": "m·g·h = k·x² ÷ 2",
          "porque": "No alto e no ponto mais baixo a velocidade é zero. Então toda a energia potencial gravitacional perdida vira energia elástica.",
          "tipo": "calcular"
        },
        {
          "faz": "Substitua os valores",
          "conta": "120 × 10 × 30 = k × 20² ÷ 2",
          "porque": "m = 120 kg, g = 10 m/s², h = 30 m e x = 20 m. O lado esquerdo vale 36 000 J.",
          "tipo": "calcular"
        },
        {
          "faz": "Isole k",
          "conta": "k = 2 × 36 000 ÷ 400 = 180",
          "porque": "O 2 do denominador passa multiplicando e x² = 400 passa dividindo. O resultado sai em N/m.",
          "tipo": "calcular"
        },
        {
          "faz": "Ligue o valor à alternativa",
          "conta": "k = 180 N/m → letra E",
          "porque": "É o menor k que faz a pessoa parar no chão. Qualquer k menor a deixaria bater no chão em movimento.",
          "tipo": "concluir"
        }
      ],
      "motivo": "Separa o cálculo de k do passo final, que liga o valor à letra, e encurta as contas para o celular."
    },
    {
      "campo": "resolucao.erradas.A",
      "depois": "Não confere: com k = 30 N/m e x = 20 m, o elástico guarda só 30 × 20² ÷ 2 = 6 000 J, bem menos que os 36 000 J perdidos até o chão. A pessoa bateria no chão em movimento.",
      "motivo": "Escreve a causa do erro no formato do guia ('não confere' com o teste que derruba a alternativa)."
    },
    {
      "campo": "resolucao.erradas.D",
      "depois": "Não confere: com k = 160 N/m e x = 20 m, o elástico guarda 160 × 400 ÷ 2 = 32 000 J, menos que os 36 000 J perdidos. Faltam 4 000 J, e a pessoa chegaria ao chão em movimento.",
      "motivo": "Padroniza o formato e deixa claro o que faltou no raciocínio de quem marcou D."
    }
  ],
  "didatica_alertas": [],
  "didatica_ok": true
}
